USE `cxView`;
DROP PROCEDURE IF EXISTS `SP_TAS009_LISTAR_MENUS_POR_MODULO`;
DROP PROCEDURE IF EXISTS `SP_TAS011_LISTAR_SUBMENUS_POR_MENU`;
DROP PROCEDURE IF EXISTS `SP_TAS015_LISTAR_OPCIONES_POR_SUBMENU`;
DROP PROCEDURE IF EXISTS `SP_TAS_USER_ACCESS_GET`;
DROP PROCEDURE IF EXISTS `SP_TAS016_ASIGNAR_OPCION_USUARIO`;
DROP PROCEDURE IF EXISTS `SP_TAS_USER_ACCESS_REMOVE`;
DELIMITER $$
CREATE PROCEDURE `SP_TAS009_LISTAR_MENUS_POR_MODULO`(IN idmodulo varchar(36)) BEGIN SELECT `IDMENU`,`IDMOD`,`NOMMENU`,`DESCMENU`,`ESTMENU`,`SACRG` FROM `TAS009` WHERE `IDMOD`=TRIM(idmodulo) ORDER BY `NOMMENU`; END$$
CREATE PROCEDURE `SP_TAS011_LISTAR_SUBMENUS_POR_MENU`(IN idmenu varchar(36)) BEGIN SELECT `IDSUBMENU`,`IDMENU`,`NOMSUBMNU`,`DESCSUBMNU`,`ESTSUBMNU`,`SACRG` FROM `TAS011` WHERE `IDMENU`=TRIM(idmenu) ORDER BY `NOMSUBMNU`; END$$
CREATE PROCEDURE `SP_TAS015_LISTAR_OPCIONES_POR_SUBMENU`(IN idsubmenu varchar(36)) BEGIN SELECT `IDOPCFOMR`,`IDSUBMENU`,`IDSMSN`,`NOMOPC`,`DESCOPC`,`ESTOPC`,`SACRG` FROM `TAS015` WHERE `IDSUBMENU`=TRIM(idsubmenu) ORDER BY `NOMOPC`; END$$
CREATE PROCEDURE `SP_TAS_USER_ACCESS_GET`(IN iduser varchar(36))
BEGIN
 IF NOT EXISTS(SELECT 1 FROM `TAS006` WHERE `IDUSER`=TRIM(iduser)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='El usuario no existe.'; END IF;
 SELECT IFNULL(a.`IDMODUSU`,'') ACCESSID,m.`IDMOD` RESOURCEID,m.`IDAPP` PARENTID,m.`NOMMOD` NAME,m.`DESCMOD` DESCRIPTION,IF(a.`IDMODUSU` IS NULL,0,1) ASSIGNED,IF(a.`ESTMODUSU`='A' AND a.`SACRG`=1,1,0) ISACTIVE FROM `TAS007` m LEFT JOIN `TAS008` a ON a.`IDMOD`=m.`IDMOD` AND a.`IDUSER`=TRIM(iduser) WHERE m.`SACRG`=1 ORDER BY m.`NOMMOD`;
 SELECT IFNULL(a.`IDMENUUSU`,'') ACCESSID,m.`IDMENU` RESOURCEID,m.`IDMOD` PARENTID,m.`NOMMENU` NAME,m.`DESCMENU` DESCRIPTION,IF(a.`IDMENUUSU` IS NULL,0,1) ASSIGNED,IF(a.`ESTMENUUSU`='A' AND a.`SACRG`=1,1,0) ISACTIVE FROM `TAS009` m LEFT JOIN `TAS010` a ON a.`IDMENU`=m.`IDMENU` AND a.`IDUSER`=TRIM(iduser) WHERE m.`SACRG`=1 ORDER BY m.`NOMMENU`;
 SELECT IFNULL(a.`IDSMUSER`,'') ACCESSID,s.`IDSUBMENU` RESOURCEID,s.`IDMENU` PARENTID,s.`NOMSUBMNU` NAME,s.`DESCSUBMNU` DESCRIPTION,IF(a.`IDSMUSER` IS NULL,0,1) ASSIGNED,IF(a.`ESTSMUSER`='A' AND a.`SACRG`=1,1,0) ISACTIVE FROM `TAS011` s LEFT JOIN `TAS012` a ON a.`IDSUBMENU`=s.`IDSUBMENU` AND a.`IDUSER`=TRIM(iduser) WHERE s.`SACRG`=1 ORDER BY s.`NOMSUBMNU`;
 SELECT IFNULL(a.`IDOPCFORMUSU`,'') ACCESSID,o.`IDOPCFOMR` RESOURCEID,o.`IDSUBMENU` PARENTID,o.`NOMOPC` NAME,o.`DESCOPC` DESCRIPTION,IF(a.`IDOPCFORMUSU` IS NULL,0,1) ASSIGNED,IF(a.`ESTOPC`='A' AND a.`SACRG`=1,1,0) ISACTIVE FROM `TAS015` o LEFT JOIN `TAS016` a ON a.`IDOPCFOMR`=o.`IDOPCFOMR` AND a.`IDUSER`=TRIM(iduser) WHERE o.`SACRG`=1 ORDER BY o.`NOMOPC`;
END$$
CREATE PROCEDURE `SP_TAS016_ASIGNAR_OPCION_USUARIO`(IN iduser varchar(36),IN idopcion varchar(36),IN usuario varchar(20))
BEGIN
 IF NOT EXISTS(SELECT 1 FROM `TAS006` WHERE `IDUSER`=TRIM(iduser) AND `ESTUSER`='A' AND `SACRG`=1) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='El usuario no existe o no está activo.'; END IF;
 IF NOT EXISTS(SELECT 1 FROM `TAS015` WHERE `IDOPCFOMR`=TRIM(idopcion) AND `ESTOPC`='A' AND `SACRG`=1) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='La opción no existe o no está activa.'; END IF;
 IF NOT EXISTS(SELECT 1 FROM `TAS015` o JOIN `TAS012` a ON a.`IDSUBMENU`=o.`IDSUBMENU` AND a.`IDUSER`=TRIM(iduser) AND a.`ESTSMUSER`='A' AND a.`SACRG`=1 WHERE o.`IDOPCFOMR`=TRIM(idopcion) AND o.`IDSUBMENU` IS NOT NULL) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='La opción no tiene un submenú activo asignado al usuario.'; END IF;
 IF EXISTS(SELECT 1 FROM `TAS016` WHERE `IDUSER`=TRIM(iduser) AND `IDOPCFOMR`=TRIM(idopcion)) THEN UPDATE `TAS016` SET `ESTOPC`='A',`SACRG`=1,`CULUSA`=NULLIF(TRIM(usuario),''),`FCHHRAACT`=CURRENT_TIMESTAMP(6) WHERE `IDUSER`=TRIM(iduser) AND `IDOPCFOMR`=TRIM(idopcion); ELSE INSERT INTO `TAS016`(`IDOPCFORMUSU`,`IDOPCFOMR`,`IDUSER`,`ESTOPC`,`SACRG`,`CUSCRT`,`FCHHRACRT`) VALUES(UUID(),TRIM(idopcion),TRIM(iduser),'A',1,NULLIF(TRIM(usuario),''),CURRENT_TIMESTAMP(6)); END IF;
 SELECT `IDOPCFORMUSU`,`IDOPCFOMR`,`IDUSER`,`ESTOPC`,`SACRG`,`CUSCRT`,`FCHHRACRT`,`CULUSA`,`FCHHRAACT` FROM `TAS016` WHERE `IDUSER`=TRIM(iduser) AND `IDOPCFOMR`=TRIM(idopcion) LIMIT 1;
END$$
CREATE PROCEDURE `SP_TAS_USER_ACCESS_REMOVE`(IN iduser varchar(36),IN idaccess varchar(36),IN usuario varchar(20))
BEGIN
 DECLARE result int DEFAULT 0;
 IF EXISTS(SELECT 1 FROM `TAS008` WHERE `IDMODUSU`=TRIM(idaccess) AND `IDUSER`=TRIM(iduser)) THEN UPDATE `TAS008` SET `ESTMODUSU`='I',`SACRG`=0,`CULUSA`=NULLIF(TRIM(usuario),''),`FCHHRAACT`=CURRENT_TIMESTAMP(6) WHERE `IDMODUSU`=TRIM(idaccess) AND `IDUSER`=TRIM(iduser); SET result=1;
 ELSEIF EXISTS(SELECT 1 FROM `TAS010` WHERE `IDMENUUSU`=TRIM(idaccess) AND `IDUSER`=TRIM(iduser)) THEN UPDATE `TAS010` SET `ESTMENUUSU`='I',`SACRG`=0,`CULUSA`=NULLIF(TRIM(usuario),''),`FCHHRAACT`=CURRENT_TIMESTAMP(6) WHERE `IDMENUUSU`=TRIM(idaccess) AND `IDUSER`=TRIM(iduser); SET result=1;
 ELSEIF EXISTS(SELECT 1 FROM `TAS012` WHERE `IDSMUSER`=TRIM(idaccess) AND `IDUSER`=TRIM(iduser)) THEN UPDATE `TAS012` SET `ESTSMUSER`='I',`SACRG`=0,`CULUSA`=NULLIF(TRIM(usuario),''),`FCHHRAACT`=CURRENT_TIMESTAMP(6) WHERE `IDSMUSER`=TRIM(idaccess) AND `IDUSER`=TRIM(iduser); SET result=1;
 ELSEIF EXISTS(SELECT 1 FROM `TAS016` WHERE `IDOPCFORMUSU`=TRIM(idaccess) AND `IDUSER`=TRIM(iduser)) THEN UPDATE `TAS016` SET `ESTOPC`='I',`SACRG`=0,`CULUSA`=NULLIF(TRIM(usuario),''),`FCHHRAACT`=CURRENT_TIMESTAMP(6) WHERE `IDOPCFORMUSU`=TRIM(idaccess) AND `IDUSER`=TRIM(iduser); SET result=1; END IF;
 SELECT result AS RESULTADO;
END$$
DELIMITER ;
